/* ---------- new keys of a child (task "Einladungen") ---------- */
const ktoNeuText = (e) => 'bq-konto-neu|' + ktoKanon({ ...e, sig: undefined });
/* the keys of a child's anchor along his announcements (task "Neuer Schluessel"): kette = [{ area, event, sig }] with
