export const PW_BASES=['password','passwort','passwd','qwerty','qwertz','asdfgh','yxcvbn','zxcvbn','iloveyou','letmein','welcome','willkommen','monkey','dragon','football','fussball','baseball','soccer','superman','batman','starwars','princess','prinzessin','sunshine','admin','administrator','hallo','hello','geheim','secret','schatz','master','shadow','freedom','whatever','trustno','changeme','abc','test','user','login','iloveu','pokemon','minecraft','fortnite','roblox','unicorn','bigquest','school','schule'];
export function pwSuggest(zufall = (n) => crypto.getRandomValues(new Uint32Array(n))){
  const r=zufall(4);
  const w=i=>{ const x=PW_WORDS[r[i]%PW_WORDS.length]; return x[0].toUpperCase()+x.slice(1); };
  return `${w(0)}-${w(1)}-${w(2)}-${String(r[3]%10000).padStart(4,'0')}`;
}
export function pwWeak(pw, user){
  const p=String(pw||''), l=p.toLowerCase(), core=l.replace(/[^a-z0-9]/g,'');
  if(p.length<12) return true;
  if(/^(.{1,4})\1+$/.test(l) || /^(.{1,4})\1+$/.test(core)) return true;            // aaaa…, abcabc…, 1212…
  const runs=['01234567890123456789','98765432109876543210','abcdefghijklmnopqrstuvwxyz','zyxwvutsrqponmlkjihgfedcba','qwertyuiopasdfghjklzxcvbnm','qwertzuiopasdfghjklyxcvbnm','1qaz2wsx3edc4rfv5tgb','zaq12wsxcde34rfvbgt5'];
  if(core.length>=8 && runs.some(s=>s.includes(core))) return true;                     // 123456789012, qwertyuiopas
  const letters=l.replace(/[^a-z]/g,'');
  if(PW_BASES.some(b=>letters===b || letters===b+b || (letters.startsWith(b) && letters.length-b.length<=2))) return true;   // password1234, Passwort!2026
  if(/^[0-9\W_]+$/.test(p) && new Set(core).size<=4) return true;                     // 111222333444, 1212…
  const parts=(l.match(/[a-z]+/g)||[]).length;   // several short words (Jam-Ox-Cup-3571) are not "one word"
  if((/^[a-z]{1,8}[0-9]+$/.test(core) || /^[0-9]+[a-z]{1,8}$/.test(core)) && (parts===1 || letters.length<6)) return true;     // one word (or name) plus digits: Beispielkind123456
  const digits=l.replace(/[^0-9]/g,''); if(letters.length>=3 && digits.length>=3 && runs.some(x=>x.includes(letters)) && runs.some(x=>x.includes(digits))) return true;   // a1b2c3d4e5f6
  const u=String(user||'').toLowerCase(); if(u.length>=3 && letters.replace(u,'').length<4) return true;   // the name plus digits
  return false;
}
